begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table gradebook_fixture(first_source uuid,second_source uuid,first_mark uuid,second_mark uuid,selection jsonb);grant select,insert,update on gradebook_fixture to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','9e100000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Gradebook school course','Synthetic sources','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id,policy_version)values('10000000-0000-4000-8000-000000000001','9e110000-0000-4000-8000-000000000001','9e100000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Gradebook first task','School work',10,'61000000-0000-4000-8000-000000000001',2),('10000000-0000-4000-8000-000000000001','9e110000-0000-4000-8000-000000000002','9e100000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Gradebook second task','School work',10,'61000000-0000-4000-8000-000000000001',2);
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
insert into gradebook_fixture(first_source)select internal.create_learning_submission('9e110000-0000-4000-8000-000000000001','Immutable first school work');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000018',true);
update gradebook_fixture set second_source=internal.create_learning_submission('9e110000-0000-4000-8000-000000000002','Immutable second school work');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
update gradebook_fixture set first_mark=internal.mark_submission(first_source,0,'Explicit native zero',2,0,true),second_mark=internal.mark_submission(second_source,7,'Reviewed second source',2,0,true);
update gradebook_fixture set selection=jsonb_build_array(jsonb_build_object('markingId',first_mark,'submissionId',first_source,'expectedRevision',1,'expectedSubmissionRevision',1,'expectedPolicyVersion',2,'parentVisible',true),jsonb_build_object('markingId',second_mark,'submissionId',second_source,'expectedRevision',1,'expectedSubmissionRevision',1,'expectedPolicyVersion',2,'parentVisible',false));
select lives_ok($$select internal.read_course_gradebook('9e100000-0000-4000-8000-000000000001',25,10,null,null)$$,'Current teacher reads named class grid');
select is(jsonb_array_length(internal.read_course_gradebook('9e100000-0000-4000-8000-000000000001',1,1,null,null)->'items'),1,'Learner row page is bounded');
select is(jsonb_array_length(internal.read_course_gradebook('9e100000-0000-4000-8000-000000000001',1,1,null,null)->'assessments'),1,'Assessment column page is bounded independently');
select is(internal.read_gradebook_source((select first_source from gradebook_fixture))->'currentResult'->>'score','0','Exact source detail retains numeric zero');
select is(jsonb_array_length(internal.preview_gradebook_release('9e100000-0000-4000-8000-000000000001',(select selection from gradebook_fixture))->'items'),2,'Preview reviews each selected source without releasing');
select throws_ok($$select internal.release_gradebook_selection('9e100000-0000-4000-8000-000000000001',jsonb_build_object('selections',jsonb_set((select selection from gradebook_fixture),'{1,expectedRevision}','2'),'confirmRelease',true),'gradebook-stale',repeat('a',64),'gradebook-golden')$$,'22023',null,'One stale selected revision rejects the whole batch');
select is((select count(*)from app.result_revisions where assessment_id in('9e110000-0000-4000-8000-000000000001','9e110000-0000-4000-8000-000000000002')),0::bigint,'Failed batch leaves no result revision');
select throws_ok($$select internal.release_gradebook_selection('9e100000-0000-4000-8000-000000000001',jsonb_build_object('selections',(select selection from gradebook_fixture),'confirmRelease',false),'gradebook-unconfirmed',repeat('b',64),'gradebook-golden')$$,'22023',null,'Human selected-release confirmation is required');
select lives_ok($$select internal.release_gradebook_selection('9e100000-0000-4000-8000-000000000001',jsonb_build_object('selections',(select selection from gradebook_fixture),'confirmRelease',true),'gradebook-confirmed',repeat('c',64),'gradebook-golden')$$,'Confirmed exact selection releases all sources atomically');
select lives_ok($$select internal.release_gradebook_selection('9e100000-0000-4000-8000-000000000001',jsonb_build_object('selections',(select selection from gradebook_fixture),'confirmRelease',true),'gradebook-confirmed',repeat('c',64),'gradebook-golden')$$,'Original-key replay returns the exact receipt');
select is((select count(*)from app.result_revisions where assessment_id in('9e110000-0000-4000-8000-000000000001','9e110000-0000-4000-8000-000000000002')),2::bigint,'Replay creates no duplicate native results');
select is((select count(*)from app.academic_evidence where source_object_id in(select first_source from gradebook_fixture union all select second_source from gradebook_fixture)),2::bigint,'One immutable evidence record per released source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000005',true);
select throws_ok($$select internal.read_course_gradebook('9e100000-0000-4000-8000-000000000001',25,10,null,null)$$,'42501',null,'Other teacher class access is denied');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select throws_ok($$select internal.read_gradebook_source((select first_source from gradebook_fixture))$$,'42501',null,'Student cannot open staff gradebook detail');
reset role;
select ok(not has_function_privilege('authenticated','internal.read_course_gradebook(uuid,integer,integer,uuid,uuid)','EXECUTE')and not has_function_privilege('cuevo_worker','internal.release_gradebook_selection(uuid,jsonb,text,text,text)','EXECUTE'),'Browser/worker receive no private gradebook grant');
select is((select count(*)from internal.outbox_events where school_id='10000000-0000-4000-8000-000000000001'and entity_id in(select id from app.result_revisions where assessment_id in('9e110000-0000-4000-8000-000000000001','9e110000-0000-4000-8000-000000000002'))and type='result.released'),2::bigint,'Every selected release retains its normal source event');
select*from finish();rollback;
